-- Guide editor redesign: guide blocks and the Alternatives template.
--  * guides.cover_alt: the cover image's alt text (asked for in the editor's Cover panel).
--  * guides.prices_checked_on: Alternatives guides only, the date competitor prices were last
--    checked; shown in the disclosure and required to publish (lib/guide-template.ts).
--  * The "Alternatives" guide category, if there isn't one yet (slug alternatives).
--  * A DRAFT example guide, "5 Best Fiverr Alternatives…", using every guide block, with
--    [placeholders] for every competitor price, fee or fact. Inserted only if the slug is free.
-- Guide blocks themselves need no schema change: they're nodes in body_json, cleaned field by field
-- by the sanitizer (lib/guide-blocks.ts). schema.sql has the same objects (not the example guide).

begin;

alter table guides
  add column cover_alt text check (char_length(cover_alt) <= 200),
  add column prices_checked_on date;
grant select (cover_alt, prices_checked_on) on guides to anon, authenticated;

insert into guide_categories (name, slug, description, color, sort_order, show_in_tabs)
select 'Alternatives', 'alternatives',
  'Honest comparisons of the platforms and services people use to hire YouTube help.',
  'violet', coalesce((select max(sort_order) + 1 from guide_categories), 0), true
where not exists (select 1 from guide_categories where slug = 'alternatives');

-- Example draft guide (generated, sanitized): every guide block, [placeholders] for competitor facts.
insert into guides (slug, title, excerpt, body_json, body_html, status, category_id)
select 'fiverr-alternatives',
  '5 Best Fiverr Alternatives for Hiring a YouTube Editor in 2026',
  'Five places to hire a video editor for your YouTube channel, compared by who they suit, how pricing works and what to watch for.',
  $doc${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fiverr is a quick way to find a video editor for a single job. If you need someone for a YouTube channel week after week, these five options are worth comparing first. "},{"type":"text","text":"[One sentence on how we compared them.]"}]},{"type":"directoryStats","attrs":{"service":"youtube-video-production-agencies"}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The short list"}]},{"type":"comparisonTable","attrs":{"rows":[{"name":"YT Agencies","bestFor":"Ongoing YouTube work with a specialist team","price":"Free to compare","difference":"Agencies that focus on YouTube, compared side by side","anchor":"yt-agencies"},{"name":"Upwork","bestFor":"[best for]","price":"[price]","difference":"[key difference]","anchor":"upwork"},{"name":"Contra","bestFor":"[best for]","price":"[price]","difference":"[key difference]","anchor":"contra"},{"name":"Toptal","bestFor":"[best for]","price":"[price]","difference":"[key difference]","anchor":"toptal"},{"name":"PeoplePerHour","bestFor":"[best for]","price":"[price]","difference":"[key difference]","anchor":"peopleperhour"}],"highlightFirst":true}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How we picked these"}]},{"type":"paragraph","content":[{"type":"text","text":"[Two or three sentences: what we looked at (vetting, pricing model, YouTube focus) and what we didn't.]"}]},{"type":"productCard","attrs":{"badge":"BEST FOR YOUTUBE SPECIALISTS","title":"YT Agencies","description":"A directory of YouTube agencies, not freelancers. You compare agencies by service, niche and starting price, then send one request and hear back from agencies that do this work.\n\nIt's our product, so we list it first and say so.","points":[{"kind":"good","text":"Free for businesses and creators to compare and send requests"},{"kind":"good","text":"Profiles show starting prices, services and the niches each agency work