":"","ctaHref":"","chooseIf":"[who this suits best]","ours":false}},{"type":"productCard","attrs":{"badge":"BEST FOR [use case]","title":"PeoplePerHour","description":"[One or two sentences on what PeoplePerHour is and who uses it to hire video editors.]","points":[{"kind":"good","text":"[strength, from their public pages]"},{"kind":"good","text":"[strength]"},{"kind":"caveat","text":"[caveat, e.g. fees or how vetting works]"}],"image":"","imageAlt":"","caption":"","price":"[price or fee, from their public pricing page]","priceSource":"","ctaLabel":"","ctaHref":"","chooseIf":"[who this suits best]","ours":false}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fiverr vs YT Agencies"}]},{"type":"abTable","attrs":{"aLabel":"Fiverr","bLabel":"YT Agencies","rows":[{"label":"Who you hire","a":"Individual freelancers","b":"Agencies"},{"label":"Pricing","a":"[price model, from Fiverr's public pages]","b":"Free to compare; agencies set their own prices"},{"label":"Best for","a":"One-off edits","b":"Ongoing channel work"},{"label":"Fees","a":"[buyer fee]","b":"No fee for businesses and creators"}],"bBetter":"You need the same team every week, want strategy as well as editing, or care about a track record on YouTube specifically."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hiring on a marketplace: what to expect"}]},{"type":"prosCons","attrs":{"good":["Fast to find someone for a small job","Easy to compare portfolios","[good point]"],"watch":["Quality varies a lot between sellers","Fees can add up on long projects [check]","[watch-out]"]}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Frequently asked questions"}]},{"type":"faq","attrs":{"items":[{"q":"Is YT Agencies free?","a":"Yes, for businesses and creators. Agencies can pay for a Pro plan; Pro agencies are shown first and always marked with a Pro badge."},{"q":"How much does a YouTube editor cost on these platforms?","a":"[Answer from the platforms' public pricing pages, with the date checked.]"},{"q":"Freelancer or agency: which should I hire?","a":"[Two or three sentences on the trade-off.]"}]}},{"type":"ctaBox","attrs":{"heading":"Compare YouTube agencies that edit for channels like yours","lines":["See starting prices and the niches each agency works in.","Free for businesses and creators."],"primaryLabel":"Browse agencies","primaryHref":"/agencies","secondaryLabel":"Request proposals","secondaryHref":"/request-proposals"}},{"type":"paragraph","content":[{"type":"text","text":"Read more: "},{"type":"text","text":"how much a YouTube agency costs","marks":[{"type":"link","attrs":{"href":"/guides"}}]},{"type":"text","text":"."}]}]}$doc$::jsonb,
